/**
 * tus `httpStack` 的薄适配。`send` 走已有的 `request.fetch`，不自己发 `wx.request`。
 * `withCredentials: false`：登录态和签名由 tus 的 `onBeforeRequest` 写入 header。
 *
 * 小程序没有 `AbortController`。取消用下面这个 signal：`WxRequest.fetch` 看到
 * `aborted` 或 `abort` 事件后调用 `RequestTask.abort()`。
 */

export interface FetchResponseLike {
  statusCode?: number
  status?: number
  header?: Record<string, unknown> | { get?: (name: string) => string | null }
  data?: unknown
}

/** 与适配器 `IFetchOptions.signal` 对齐，不依赖平台上的 `AbortSignal`。 */
export interface TusAbortSignal {
  aborted: boolean
  addEventListener(event: string, listener: () => void): void
  removeEventListener(event: string, listener: () => void): void
}

export interface TusFetchOptions {
  url: string
  method: string
  headers: Record<string, string>
  body?: unknown
  withCredentials: false
  signal?: TusAbortSignal
}

export type TusFetch = (options: TusFetchOptions) => Promise<FetchResponseLike>

export class FetchHttpStack {
  constructor(private readonly fetch: TusFetch) {}

  createRequest(method: string, url: string): FetchHttpRequest {
    return new FetchHttpRequest(this.fetch, method, url)
  }

  getName(): string {
    return 'FetchHttpStack'
  }
}

export function createFetchHttpStack(fetch: TusFetch): FetchHttpStack {
  return new FetchHttpStack(fetch)
}

function createRequestAbort(): { signal: TusAbortSignal; abort: () => void } {
  const listeners: Array<() => void> = []
  const signal: TusAbortSignal = {
    aborted: false,
    addEventListener(event, listener) {
      if (event === 'abort') listeners.push(listener)
    },
    removeEventListener(event, listener) {
      if (event !== 'abort') return
      const index = listeners.indexOf(listener)
      if (index >= 0) listeners.splice(index, 1)
    },
  }
  return {
    signal,
    abort() {
      if (signal.aborted) return
      signal.aborted = true
      listeners.slice().forEach(listener => listener())
    },
  }
}

export class FetchHttpRequest {
  private readonly headers: Record<string, string> = {}
  private readonly requestAbort = createRequestAbort()

  constructor(
    private readonly fetch: TusFetch,
    private readonly method: string,
    private readonly url: string,
  ) {}

  getMethod(): string {
    return this.method
  }

  getURL(): string {
    return this.url
  }

  setHeader(header: string, value: string): void {
    this.headers[header] = value
  }

  getHeader(header: string): string | null {
    const found = Object.keys(this.headers).find(key => key.toLowerCase() === header.toLowerCase())
    return found ? this.headers[found] : null
  }

  setProgressHandler(_handler: (bytesSent: number) => void): void {
    // request.fetch 没有分片内的上传进度。tus 在每片被接受后自行累计。
  }

  send(body?: unknown): Promise<FetchHttpResponse> {
    return this.fetch({
      url: this.url,
      method: this.method,
      headers: this.headers,
      ...(body !== undefined && body !== null ? { body } : {}),
      withCredentials: false,
      signal: this.requestAbort.signal,
    }).then(res => new FetchHttpResponse(res))
  }

  abort(): Promise<void> {
    this.requestAbort.abort()
    return Promise.resolve()
  }

  getUnderlyingObject(): { abort: () => void; signal: TusAbortSignal } {
    return this.requestAbort
  }
}

export class FetchHttpResponse {
  constructor(private readonly res: FetchResponseLike) {}

  getStatus(): number {
    const status = this.res.statusCode ?? this.res.status
    return typeof status === 'number' ? status : 0
  }

  getHeader(header: string): string | null {
    const headers = this.res.header
    if (!headers) return null
    if (typeof (headers as { get?: unknown }).get === 'function') {
      const value = (headers as { get: (name: string) => string | null }).get(header)
      return value === null || value === undefined ? null : String(value)
    }
    const record = headers as Record<string, unknown>
    const found = Object.keys(record).find(key => key.toLowerCase() === header.toLowerCase())
    if (!found || record[found] === null || record[found] === undefined) return null
    return String(record[found])
  }

  getBody(): string {
    const { data } = this.res
    if (typeof data === 'string') return data
    if (data === null || data === undefined) return ''
    if (typeof data === 'object') return JSON.stringify(data)
    return String(data)
  }

  getUnderlyingObject(): FetchResponseLike {
    return this.res
  }
}
